def norm_url(url: str) -> str:
    parsed = urlparse(url.strip())
    host = parsed.netloc.lower()
    if host.startswith("www."):
        host = host[4:]
    path = re.sub(r"/+$", "", parsed.path or "")
    return f"{host}{path}".lower()


def norm_name(name: str) -> str:
    return re.sub(r"[^a-z0-9]+", " ", name.lower()).strip()


def parse_year(value: int | str, default: int) -> int:
    if isinstance(value, int):
        return value
    digits = "".join(ch for ch in str(value) if ch.isdigit())
    return int(digits[:4]) if len(digits) >= 4 else default


def period_bands(start: int | str, end: int | str) -> str:
    s = parse_year(start, 1830)
    e = parse_year(end, 2026)
    bands: list[str] = []
    if s <= 1930 and e >= 1830:
        bands.append("1830-1930")
    if s <= 1970 and e >= 1931:
        bands.append("1931-1970")
    if s <= 2000 and e >= 1971:
        bands.append("1971-2000")
    if s <= 2026 and e >= 2001:
        bands.append("2001-2026")
    return "; ".join(bands)


def existing_keys() -> tuple[set[str], set[str]]:
    urls: set[str] = set()
    names: set[str] = set()
    for path in EXISTING_SOURCE_FILES:
        if not path.exists():
            continue
        with path.open(newline="", encoding="utf-8") as f:
            for row in csv.DictReader(f):
                url = row.get("url") or row.get("base_url") or row.get("source_url") or ""
                name = row.get("source_name") or row.get("name") or ""
                if url:
                    urls.add(norm_url(url))
                if name:
                    names.add(norm_name(name))
    return urls, names


def row(
    source_name: str,
    macro_region: str,
    subregion: str,
    country_or_region: str,
    source_class: str,
    institutional_level: str,
    protocol_family: str,
    url: str,
    period_start: int,
    period_end: int,
    expected_record_types: str,
    recommended_adapter: str,
    priority: str,
    rights_posture: str = "source-hosted review",
    risk_notes: str = "item rights vary; source-level discovery only",
    capture_route: str = "source-level metadata and source-link discovery",
    recommended_image_policy: str = "IMG00/IMG02 only after item-level source and rights review; no IMG01/IMG03 automatic upgrade",
    text_enrichment_path: str = "source title, description, collection scope, catalog terms, and stable links",
    inclusion_status: str = "candidate",
    notes: str = "",
) -> dict[str, str]:
    impact_score = score(macro_region, source_class, protocol_family, priority, rights_posture, expected_record_types)
    return {
        "source_name": source_name,
        "macro_region": macro_region,
        "subregion": subregion,
        "country_or_region": country_or_region,
        "source_class": source_class,
        "institutional_level": institutional_level,
        "protocol_family": protocol_family,
        "url": url,
        "period_start": str(period_start),
        "period_end": str(period_end),
        "period_bands": period_bands(period_start, period_end),
        "expected_record_types": expected_record_types,
        "capture_route": capture_route,
        "recommended_adapter": recommended_adapter,
        "recommended_image_policy": recommended_image_policy,
        "text_enrichment_path": text_enrichment_path,
        "rights_posture": rights_posture,
        "risk_notes": risk_notes,
        "priority": priority,
        "inclusion_status": inclusion_status,
        "notes": notes,
        "impact_score": str(impact_score),
        "impact_rating": rating(impact_score),
        "impact_basis": (
            f"region={macro_region}; class={source_class}; protocol={protocol_family}; "
            "internal triage only, not public authority or rights clearance"
        ),
        "new_source_basis": "not present in existing source registry, global edge, contemporary scan, or v1 nonmainstream target URL/name keys",
    }


def score(
    macro_region: str,
    source_class: str,
    protocol_family: str,
    priority: str,
    rights_posture: str,
    expected_record_types: str,
) -> int:
    value = 45
    if macro_region in {"Africa", "MENA", "South Asia", "Southeast Asia", "Central Asia"}:
        value += 18
    elif macro_region in {"Latin America / Caribbean", "Eastern Europe / Caucasus", "Oceania / Indigenous"}:
        value += 15
    else:
        value += 10
    if any(term in source_class.lower() for term in ("design", "poster", "ephemera", "archive", "visual")):
        value += 10
    if any(term in expected_record_types.lower() for term in ("poster", "ephemera", "newspaper", "periodical", "typography", "advertising")):
        value += 8
    if any(term in protocol_family.lower() for term in ("api", "iiif", "oai", "wordpress", "catalog")):
        value += 7
    if priority == "P0":
        value += 8
    elif priority == "P1":
        value += 4
    if "community" in rights_posture or "protocol" in rights_posture:
        value -= 2
    return max(1, min(value, 100))


def rating(value: int) -> str:
    if value >= 82:
        return "A"
    if value >= 68:
        return "B"
    return "C"


